function ALL_CLIQUES(V, E):
    faces <- { empty_set }
    frontier <- [ (empty_set, sorted(V)) ]
    while frontier not empty:
        (C, candidates) <- pop(frontier)
        for index i, vertex v in candidates:
            C' <- C union {v}
            faces <- faces union { C' }
            ext <- [ u in candidates[i+1:] :
                       u adjacent to every w in C' ]
            if ext nonempty: push (C', ext) to frontier
    return faces

function IS_FLAG(faces):
    V <- { a : {a} in faces }
    E <- { {a,b} in faces : a != b }
    for each vertex subset s with |s| >= 2:
        if every pair of s lies in E and s not in faces:
            return False        # hollow simplex certificate
    return True
